/* Add Null Function */
void DBC_add_null_resloc_list(struct RESLOC_LIST_N_TAG *RESLOC_LIST_N, struct RESLOC_LIST_TAG *RESLOC_LIST)
{ 
    /* memset by NULL */
    memset(RESLOC_LIST_N, '\0', sizeof(struct RESLOC_LIST_N_TAG));

    MEMCPY_AN(RESLOC_LIST_N->FACTORY ,RESLOC_LIST->FACTORY ,sizeof(RESLOC_LIST->FACTORY ));
    MEMCPY_AN(RESLOC_LIST_N->RES_ID ,RESLOC_LIST->RES_ID ,sizeof(RESLOC_LIST->RES_ID ));
    MEMCPY_AN(RESLOC_LIST_N->RES_DESC ,RESLOC_LIST->RES_DESC,sizeof(RESLOC_LIST->RES_DESC));
    RESLOC_LIST_N->ATTACHED_FLAG[0]= RESLOC_LIST->ATTACHED_FLAG;
    MEMCPY_AN(RESLOC_LIST_N->LAYOUT_ID ,RESLOC_LIST->LAYOUT_ID,sizeof(RESLOC_LIST->LAYOUT_ID));
    RESLOC_LIST_N->UP_DOWN_FLAG[0]= RESLOC_LIST->UP_DOWN_FLAG;
}


/* Del Null Function */
void DBC_del_null_resloc_list(struct RESLOC_LIST_N_TAG *RESLOC_LIST_N, struct RESLOC_LIST_TAG *RESLOC_LIST)
{
    MEMCPY_DN(RESLOC_LIST->FACTORY ,RESLOC_LIST_N->FACTORY ,sizeof(RESLOC_LIST->FACTORY ));
    MEMCPY_DN(RESLOC_LIST->RES_ID ,RESLOC_LIST_N->RES_ID ,sizeof(RESLOC_LIST->RES_ID ));
    MEMCPY_DN(RESLOC_LIST->RES_DESC ,RESLOC_LIST_N->RES_DESC,sizeof(RESLOC_LIST->RES_DESC));
    RESLOC_LIST->ATTACHED_FLAG = RESLOC_LIST_N->ATTACHED_FLAG[0];
    MEMCPY_DN(RESLOC_LIST->LAYOUT_ID ,RESLOC_LIST_N->LAYOUT_ID,sizeof(RESLOC_LIST->LAYOUT_ID));
    RESLOC_LIST->UP_DOWN_FLAG = RESLOC_LIST_N->UP_DOWN_FLAG[0];
}      

